{
  "assay_type": "Cellular concentration-response assay for growth/proliferation or viability",
  "system": "Mouse BaF3 cells engineered to express MER (Q12866); the MER construct, expression level, selection method, and cytokine/growth-factor conditions are unresolved.",
  "readout": "After 48 hours of compound exposure, measure intracellular ATP by CellTiter-Glo luminescence as a surrogate for viable cell number. The 48-hour endpoint and readout are supported by the retained descriptions of CHEMBL4822428; this is not a direct measurement of MER kinase activity.",
  "steps": [
    {
      "card_id": "cell-prepare",
      "instruction": "Plate MER-expressing BaF3 cells and prepare a CHEMBL169390 dilution series with constant vehicle concentration across treated and vehicle-control wells. Include untreated, vehicle, background, and reference-control wells. Include MER-negative parental BaF3 cells, cultured identically, as a provisional comparator for MER-dependent effects.",
      "parameters": {
        "cell_density": "unresolved; optimize to remain in the assay's linear range and avoid control-cell overgrowth during 48 hours",
        "medium": "unresolved; use the medium and growth-factor conditions required by the validated BaF3/MER system and keep them identical across comparisons",
        "top_concentration_uM": "10 uM; provisional exploratory design assumption, not a sourced property of CHEMBL169390",
        "dilution_factor": "3-fold; provisional design assumption",
        "n_points": "10; provisional design assumption spanning approximately 0.00051-10 uM",
        "replicates": "3 independent experiments; provisional design assumption, with technical replicate number unresolved",
        "vehicle_fraction": "unresolved; keep constant and verify that the selected concentration does not affect the readout"
      }
    },
    {
      "card_id": "cell-expose",
      "instruction": "Expose the cells to CHEMBL169390 or controls for 48 hours. Apply the same exposure schedule to the parental-cell comparator and all controls.",
      "parameters": {
        "exposure_time": "48 hours (2 days), supported by the retained CHEMBL4822428 assay descriptions",
        "temperature": "unresolved in the packet; use the validated culture condition for the cell system"
      }
    },
    {
      "card_id": "cell-detect",
      "instruction": "Apply CellTiter-Glo, mix and stabilize according to the validated reagent procedure, and record luminescence. Include cell-free medium-plus-reagent wells for background. No adaptation to the biochemical kinase cards is needed because the requested endpoint is cellular viability.",
      "parameters": {
        "reagent_volume": "unresolved; follow the validated procedure and well volume",
        "mix_time": "unresolved; follow the validated procedure",
        "stabilization_time": "unresolved; follow the validated procedure and use a consistent plate-reading interval"
      }
    },
    {
      "card_id": "analyse",
      "instruction": "Subtract background, normalize treated wells to vehicle controls, and fit CHEMBL169390 concentration against normalized luminescence. Report the fitted cellular IC50 with confidence intervals, individual replicate data, curve quality, and any incomplete inhibition or failure to reach a fitted IC50. Compare MER-expressing and parental cells without treating that comparison alone as proof of direct MER inhibition.",
      "parameters": {
        "fit_model": "four-parameter log-logistic concentration-response model as a provisional analysis assumption; use an appropriate alternative if the data do not support a stable four-parameter fit",
        "acceptance_criteria": "Predefine acceptable vehicle growth, background, replicate variability, control performance, and curve-fit quality before analysis; numerical thresholds are unresolved. Do not report a precise IC50 when the response range or fit does not support one."
      }
    }
  ],
  "top_concentration_uM": 10,
  "dilution_factor": 3,
  "n_points": 10,
  "replicates": 3,
  "controls": [
    "Vehicle-only MER-expressing BaF3 cells for normalization",
    "Untreated MER-expressing BaF3 cells to assess vehicle effects",
    "Cell-free medium and detection reagent for luminescence background",
    "A validated assay reference compound, with its identity and concentration unresolved",
    "MER-negative parental BaF3 cells exposed to the same series as a provisional specificity comparator",
    "Optional positive cytotoxicity control to confirm assay responsiveness; identity unresolved"
  ],
  "rationale": "The cellular cards match the requested BaF3/MER system and viability endpoint. Retained examples for other compounds in CHEMBL4822428 support a two-day CellTiter-Glo measurement in recombinant human Mer-expressing mouse BaF3 cells, but their IC50 values are contextual and do not estimate CHEMBL169390 potency. The broad 10-point series and three independent experiments are explicitly provisional design choices intended to locate a response without predicting a withheld IC50. Biochemical kinase steps were omitted because they would measure a different endpoint and are not required for this cellular assay.",
  "citations": [
    "CHEMBL4822428",
    "CHEMBL4819114",
    "CHEMBL169390",
    "Q12866"
  ],
  "limitations": [
    "No CHEMBL169390 measurement is supplied; the concentration range, replicate plan, and analysis settings are assumptions rather than sourced compound-specific conditions.",
    "Cell density, medium, growth factors, vehicle fraction, culture temperature, detection volumes and timing, reference controls, and quantitative acceptance thresholds remain unresolved.",
    "ATP luminescence reflects viable cell number/metabolic ATP and cannot by itself distinguish reduced proliferation from cell death or nonspecific metabolic effects.",
    "Reduced viability does not establish direct binding to or biochemical inhibition of Tyrosine-protein kinase Mer, nor does it establish MER-specific causality or selectivity against other kinases.",
    "A parental-cell difference would support, but not prove, MER dependence; stronger causal claims require orthogonal MER pathway-engagement and genetic or rescue controls, plus direct biochemical testing if direct inhibition is claimed.",
    "The retained examples concern other compounds and recombinant human Mer; compatibility with the exact MER construct used here must be confirmed."
  ]
}
